package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Persistent entity types (excluding Find/Update/Delete DTOs and infrastructure)
var entityTypes = []string{
	"Attachment",
	"IdentityProvider",
	"Inbox",
	"InstanceSetting",
	"Memo",
	"MemoRelation",
	"MemoShare",
	"Reaction",
	"User",
	"UserIdentity",
	"UserSetting",
	"AuthenticationConfigState",
}

func main() {
	root := "/bench/repo"
	fset := token.NewFileSet()

	// type -> set of package paths
	typePkgRefs := make(map[string]map[string]struct{})

	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || !strings.HasSuffix(path, ".go") {
			return nil
		}
		// Skip vendor, .git, web, proto gen might be separate
		if strings.Contains(path, "/.git/") || strings.Contains(path, "/node_modules/") {
			return nil
		}

		rel, _ := filepath.Rel(root, path)
		// Determine if inside store layer
		inStoreLayer := strings.HasPrefix(rel, "store"+string(filepath.Separator)) ||
			strings.HasPrefix(rel, "store/")

		dir := filepath.Dir(path)
		pkgPath := dir // use directory as package identifier

		file, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			return nil // skip unparseable
		}

		// Find store import local name
		storeLocal := ""
		for _, imp := range file.Imports {
			importPath := strings.Trim(imp.Path.Value, `"`)
			if importPath == "github.com/usememos/memos/store" {
				if imp.Name != nil {
					storeLocal = imp.Name.Name
				} else {
					storeLocal = "store"
				}
				break
			}
		}

		if storeLocal == "" {
			return nil
		}

		// Skip if in store layer and we're only counting outside
		if inStoreLayer {
			return nil
		}

		ast.Inspect(file, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.SelectorExpr:
				if ident, ok := x.X.(*ast.Ident); ok {
					if ident.Name == storeLocal {
						typeName := x.Sel.Name
						for _, et := range entityTypes {
							if typeName == et {
								if typePkgRefs[et] == nil {
									typePkgRefs[et] = make(map[string]struct{})
								}
								typePkgRefs[et][pkgPath] = struct{}{}
							}
						}
					}
				}
			}
			return true
		})

		return nil
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "walk error: %v\n", err)
		os.Exit(1)
	}

	type result struct {
		name  string
		count int
		pkgs  []string
	}
	var results []result
	for _, et := range entityTypes {
		pkgs := typePkgRefs[et]
		pkgList := make([]string, 0, len(pkgs))
		for p := range pkgs {
			pkgList = append(pkgList, p)
		}
		sort.Strings(pkgList)
		results = append(results, result{et, len(pkgs), pkgList})
	}
	sort.Slice(results, func(i, j int) bool {
		if results[i].count != results[j].count {
			return results[i].count > results[j].count
		}
		return results[i].name < results[j].name
	})

	fmt.Println("=== Rankings (packages outside store/) ===")
	for _, r := range results {
		if r.count > 0 {
			fmt.Printf("%s: %d packages\n", r.name, r.count)
			for _, p := range r.pkgs {
				rel, _ := filepath.Rel(root, p)
				fmt.Printf("  - %s\n", rel)
			}
			fmt.Println()
		}
	}
}
EOF
