python3 << 'PYEOF'
import os
import re
from collections import defaultdict

ROOT = "/bench/repo"

ENTITY_TYPES = {
    "Attachment", "IdentityProvider", "Inbox", "InstanceSetting",
    "Memo", "MemoRelation", "MemoShare", "Reaction", "User",
    "UserIdentity", "UserSetting", "AuthenticationConfigState",
}

# Also track enum-like persistent types
ENUM_TYPES = {"RowStatus", "Visibility", "Role", "InboxStatus", "MemoRelationType"}

def is_in_store_layer(rel_path):
    return rel_path.startswith("store/") or rel_path == "store"

def find_store_local(line, imports_block):
    # Parse import alias from accumulated import block
    for imp in imports_block:
        m = re.search(r'github\.com/usememos/memos/store"', imp)
        if m:
            # check for alias: alias "path" or just "path"
            alias_m = re.match(r'\s*(\w+)\s+"github\.com/usememos/memos/store"', imp)
            if alias_m:
                return alias_m.group(1)
            # blank import or named import with parens
            return "store"
    return None

def get_package_dir(filepath):
    return os.path.dirname(filepath)

def analyze_file(filepath):
    rel = os.path.relpath(filepath, ROOT)
    if is_in_store_layer(rel):
        return None  # skip store layer

    try:
        with open(filepath, 'r', errors='replace') as f:
            content = f.read()
    except:
        return None

    if 'github.com/usememos/memos/store' not in content:
        return None

    # Extract import block(s) to find alias
    store_local = None
    # Match import with alias
    for m in re.finditer(r'(\w+)\s+"github\.com/usememos/memos/store"', content):
        store_local = m.group(1)
        break
    if store_local is None:
        for m in re.finditer(r'"github\.com/usememos/memos/store"', content):
            store_local = "store"
            break

    if store_local is None:
        return None

    pkg = get_package_dir(filepath)
    refs = set()

    # Pattern: localName.TypeName (word boundary)
    for tname in ENTITY_TYPES | ENUM_TYPES:
        pattern = rf'\b{re.escape(store_local)}\.{tname}\b'
        if re.search(pattern, content):
            refs.add(tname)

    return pkg, refs

type_pkg_refs = defaultdict(set)
type_file_refs = defaultdict(set)

for dirpath, dirnames, filenames in os.walk(ROOT):
    dirnames[:] = [d for d in dirnames if d not in {'.git', 'node_modules', 'web'}]
    for fn in filenames:
        if not fn.endswith('.go'):
            continue
        fp = os.path.join(dirpath, fn)
        result = analyze_file(fp)
        if result is None:
            continue
        pkg, refs = result
        rel = os.path.relpath(fp, ROOT)
        for t in refs:
            type_pkg_refs[t].add(pkg)
            type_file_refs[t].add(rel)

all_types = sorted(ENTITY_TYPES | ENUM_TYPES)
ranked = sorted(all_types, key=lambda t: (-len(type_pkg_refs[t]), t))

